using HRIS.Api.Controllers; using HRIS.Api.DTOs.Laptop; using HRIS.Api.Exceptions; using HRIS.Api.Services; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc; using Microsoft.AspNetCore.Mvc.RazorPages;
namespace HRIS.Api.Pages.Laptops; [Authorize(AuthenticationSchemes="Cookies")] public class IndexModel:PageModel { private readonly ILaptopService _service; public IndexModel(ILaptopService service)=>_service=service; public List<LaptopResponseDto> Items{get;set;}=new(); public bool CanManage{get;set;} public async Task OnGetAsync(){var a=User.ToUserContext();CanManage=a.IsHrOrSupport;Items=await _service.GetAsync(a);} public async Task<IActionResult> OnPostCreateAsync(string model,long? price){try{await _service.CreateAsync(new LaptopCreateDto{Model=model,Price=price},User.ToUserContext());TempData["Success"]="Permintaan laptop diajukan.";}catch(Exception ex)when(ex is BadRequestException or ForbiddenException){TempData["Error"]=ex.Message;}return RedirectToPage();} public async Task<IActionResult> OnPostStatusAsync(int id,string status){try{await _service.UpdateStatusAsync(id,status,null,User.ToUserContext());TempData["Success"]="Status laptop diperbarui.";}catch(Exception ex)when(ex is BadRequestException or ForbiddenException or NotFoundException){TempData["Error"]=ex.Message;}return RedirectToPage();} }
